import { headers } from "next/headers";
import { auth, db } from "./auth";

export type User = {
  id: string;
  email: string;
  name: string;
  createdAt: string;
};

type UserRow = {
  id: string;
  email: string;
  name: string;
  createdAt: string | number;
};

function toDateString(value: string | number): string {
  const date = new Date(value);
  return date.toISOString().slice(0, 10);
}

function fromRow(row: UserRow): User {
  return {
    id: row.id,
    email: row.email,
    name: row.name,
    createdAt: toDateString(row.createdAt),
  };
}

// Accounts, passwords and sessions are all owned by Better Auth (see
// src/lib/auth.ts) — this module just reads its "user" table so the rest of
// the app doesn't need to know how auth is implemented.

export async function listUsers(): Promise<User[]> {
  const rows = db
    .prepare("SELECT id, email, name, createdAt FROM user ORDER BY createdAt ASC")
    .all() as UserRow[];
  return rows.map(fromRow);
}

